import type { AppCopy } from '../types';
import type { Locale } from '../../i18n';
import guides from '../guides/ting';
// Real screenshots of Ting 0.3.3 with a demo config. The app UI is English; keycaps also show
// the letter of the active keyboard layout (Russian here), as Ting does for any layout.
const selecta = { src: '/images/shots/ting/selecta.webp', width: 340, height: 407 };
const launcha = { src: '/images/shots/ting/launcha.webp', width: 460, height: 250 };
const light = { src: '/images/shots/ting/selecta-light.webp', width: 340, height: 407 };
const bindings = { src: '/images/shots/ting/bindings.webp', width: 820, height: 608 };
const copy: Record<Locale, AppCopy> = {
  en: {
    guide: guides.en,
    category: 'For your keyboard', tagline: 'Your next app. A few keys away.',
    shots: [
      { ...selecta, caption: 'Press the leader, then one key.', alt: 'Ting selecta menu in the dark theme: keycaps for Terminal, Safari, Notes, Calendar, Music, a Home scenes link, and Web and Tools groups. Each keycap shows the Latin key and the letter of the current keyboard layout.' },
      { ...launcha, caption: 'Double-tap the leader to search apps.', alt: 'Ting launcha search: the query “system” finds System Information and System Settings.' },
      { ...light, caption: 'Light or dark, as you like.', alt: 'The Ting selecta menu in the light theme.' },
      { ...bindings, caption: 'Every sequence in one table.', alt: 'Ting Settings, Bindings tab: a table of key sequences, names, and actions, including the Web and Tools groups.' },
    ],
    description: 'A leader-key launcher for macOS. Press your leader key, then a key or short sequence to open an app or URL, or to start a small micro-app. Home, then w, g — and you’re on GitHub. Double-tap the leader to search apps with launcha.',
    features: [
      { title: 'Ting 0.7.0: a calculator in launcha', text: 'Type digits and an operator, such as 2*(3+4), 1,5 × 4 or 200 + 15%: the value comes first in launcha, and Return copies it. Ting computes it itself, with decimal numbers, so 0.1 + 0.2 is 0.3. Turn it off with Calculate in launcha in Settings. Updates are now checked at bobuk.io.' },
      { title: 'Ting 0.6.1: an Accessibility window', text: 'When a micro-app needs Accessibility and Ting does not have it, Ting opens a window instead of an error: Open Accessibility Settings goes to the right pane of System Settings, and the Ting icon in the window drags straight into its list. The window closes by itself once access is on. Settings › Advanced shows the state.' },
      { title: 'Ting 0.6.0: context and typing', text: 'A micro-app can read what you were working on: the active app, the files selected in Finder, the browser tab, the selected text and the front window, but only what its file lists in context:. keys and paste steps press keys and paste text in the app you came from, and output to: [app] puts the result in place of the selection. The approval panel shows what a micro-app reads and sends.' },
      { title: 'Ting 0.5.1: faster menu and switching', text: 'App icons are preloaded and app paths cached when bindings load. Already running apps activate directly, before the menu hides. The menu view is reused, its window fits the content and uses the system shadow. Space and other keys without a layout hint now have the same minimum keycap width, so rows line up.' },
      { title: 'Ting 0.5.0: steps and libraries', text: 'A micro-app can now be a list of steps: shell or Python code, HTTP requests, AI calls (OpenAI, Anthropic or a local server such as Ollama), text, JSON fields, opening a URL and notifications, piped one into the next. Shared steps live once in libraries. The ting-micro console tool checks and runs micro-apps, and a coding agent can now add your bindings too.' },
      { title: 'Ting 0.4.0: micro-apps', text: 'A micro-app is one YAML file that runs one shell command: it can ask for a few parameters, read the clipboard and show or copy the result. Bind a key to it or start it from launcha. Ting runs it only after you approve the exact file. Copy Agent Prompt hands Claude Code, Codex or pi what they need to write one, and Ting --check checks the file.' },
      { title: 'Ting 0.3.3: a quieter “ting”', text: 'The sound Ting plays when it opens an app, link or file is now half as loud. Turn it off in Settings → General with Play a “ting” when opening an app, link or file.' },
      { title: 'Ting 0.3.2: complete app list', text: 'launcha now scans every app in its folders, however large or deeply nested, and no longer shows scan-limit notices.' },
      { title: 'Ting 0.3.1: closer selecta spacing', text: 'With the panel title hidden, the leader-key row now sits closer to the amber top rule, matching launcha.' },
      { title: 'New in 0.3.0: launcha', text: 'Double-tap the leader to search apps, or set a separate hotkey. Results rank by successful Ting launches over the last seven days. When no app matches, Spotlight searches indexed files in your home folder, subject to folder consent. Use Check for Updates… in Ting to upgrade.' },
      { title: 'One key to begin', text: 'Choose any non-modifier key, alone or with modifiers: Home, F13, or Option-Shift-Command-F. A modifier alone cannot be the leader. There is no default: Ting asks you on first launch.' },
      { title: 'A small menu, when you need it', text: 'Organize nested groups such as Apps and Web. Use letters, digits, Space, Return, and F-keys. Esc closes the menu; Delete goes back a level. Type quickly and the menu stays out of the way: its delay defaults to 0.25 s.' },
      { title: 'Keep your keyboard layout', text: 'Bindings use the Latin letter of each key and work with any layout, including Russian and Ukrainian. The menu shows the current layout’s letter as a small hint beside it.' },
      { title: 'Your bindings, your file', text: 'Edit ~/.config/ting/config.json by hand, keep it in dotfiles, or use Settings. Ting reloads changes automatically. Apps open or come to the front; URLs open in the default app, including schemes such as raycast://.' },
    ],
    installNote: 'Universal ZIP for Apple Silicon and Intel, with a SHA-256 checksum file. Menu-bar only, with no Dock icon. The interface is English only.',
    steps: [
      { title: 'Download and install', text: 'Download the latest release ZIP from GitHub, unzip it, and move Ting.app to /Applications. Releases are signed with Developer ID and notarized by Apple.' },
      { title: 'Choose your leader', text: 'Open Ting and press the key you want to use as your leader. The leader needs no Accessibility or Input Monitoring permission: Ting uses the standard macOS hotkey API.' },
      { title: 'Make it yours', text: 'In Settings → Bindings, record key sequences and finish with Done. Missing groups are created and empty groups removed automatically. You can also edit ~/.config/ting/config.json directly.' },
    ],
    faq: [
      { question: 'Do I need special permissions?', answer: 'The leader and launcha need no Accessibility or Input Monitoring access. Since 0.6.0 a micro-app that reads the selected text or the front window, presses keys or pastes into an app needs Accessibility, and one that reads the Finder selection or the browser tab needs Automation for that app; Ting asks only then. Since 0.6.1, without Accessibility Ting opens a window that shows how to allow it. launcha skips Desktop, Documents and Downloads until you explicitly allow access; macOS may then request folder permissions.' },
      { question: 'Can I run shell commands?', answer: 'Yes, from micro-apps since 0.4.0: YAML files in ~/.config/ting/micro/. Ting runs a command only after you approve the exact file content, as your user with your full rights, for 60 seconds by default and at most 300. Since 0.5.0 a micro-app can also run Python, HTTP requests and AI calls as steps, and since 0.6.0 it can read the active app, the Finder selection, the browser tab or the selected text and paste its result into the app. App and URL bindings run no commands; config.json holds no code.' },
      { question: 'Does it work with Russian and Ukrainian layouts?', answer: 'Yes. Bindings are stored by Latin key letter, with a small current-layout hint in the menu. You don’t need to switch layouts.' },
      { question: 'How is it different from Spotlight?', answer: 'selecta opens your fixed sequences without search; fast sequences skip the menu. launcha adds app-name search, ranked by use through Ting. Spotlight file search is a fallback only when no app matches. Since 0.7.0 launcha also calculates: type 2*(3+4) and press Return to copy 14.' },
      { question: 'Is it in the App Store?', answer: 'No. Download the universal ZIP from GitHub Releases. Built-in Sparkle updates read the feed at bobuk.io (Ting 0.6.1 and older: the GitHub release feed) and download releases from GitHub.' },
      { question: 'Why Ting?', answer: '“Ting” means “thing” in Jamaican patois and London slang. Amber keycaps, a graphite panel, and “pull up” / “rewind” hints give the menu a light nod to grime and sound-system culture.' },
    ],
    supportIntro: 'Leader keys, bindings, and help from the project. Keep private URLs and tokens out of public reports.',
    support: [
      { title: 'Leader or sequence not working?', paragraphs: [], items: ['Choose a non-modifier key, optionally with modifiers. Right Option alone cannot be a leader; Home or F13 can.', 'Check the sequence in Settings → Bindings. Finish recording with Done. Esc closes the menu and Delete goes back one group.', 'Check the menu delay and unknown key behaviour in General. The default delay is 0.25 s; quick sequences may finish before the menu appears.'] },
      { title: 'Settings and configuration', paragraphs: ['General includes Light/Dark theme (dark by default), leader, menu delay, unknown key behaviour, launch at login, menu-bar icon, and sound. Show panel title lets you hide the Ting · selecta title row while keeping the tuning-fork leader symbol and sequence visible. Advanced offers the config path, reveal, reload, import, and export, and the micro-apps folder: the found micro-apps, their errors, Open Folder in Finder and Copy Agent Prompt.', 'Settings and bindings live in ~/.config/ting/config.json. Ting reloads changes; if the file has an error, it keeps the last good settings and shows the error in its menu.'] },
      { title: 'Ting 0.7.0: a calculator in launcha', paragraphs: ['A query of digits and an operator, such as 2*(3+4), 1,5 × 4, 200 + 15%, 2^10 or sqrt(2), shows its value first, above any app or file; Return copies it and Ting says Copied. Both . and , are decimal points. + - * / ^, × ÷, parentheses, mod, percent (200 + 15% is 230), pi, e and the functions sqrt, abs, round, floor, ceil, ln, log, exp, sin, cos and tan (radians) work; results keep up to 12 digits after the point. A lone number, a version such as 1.2.3 or a division by zero shows no value. The calculator is on by default: turn it off with Calculate in launcha in Settings › General, or with "calculator": false under launcha in config.json.', 'Sparkle now checks for updates at https://bobuk.io/apps/ting/appcast.xml, so a new release shows up as soon as it is published; archives still come from GitHub Releases and are accepted only with Ting’s signature. Ting 0.6.1 and older find 0.7.0 through the GitHub feed. Choose Check for Updates… in Ting to install 0.7.0; your settings, bindings, micro-apps and permissions are kept.'] },
      { title: 'Ting 0.6.1: an Accessibility window', paragraphs: ['When a micro-app needs Accessibility (the selected text, the front window, keys, paste or output to: [app]) and Ting does not have it, Ting opens a window with the steps instead of an error panel or the prompt of macOS. Open Accessibility Settings opens System Settings › Privacy & Security › Accessibility; drag the Ting icon from the window into the list of apps, or click + and choose Ting, then turn on its switch. The window stays above System Settings and closes by itself once access is on; then start the micro-app again. A result that could not be pasted stays on the clipboard.', 'Settings › Advanced shows whether Ting has Accessibility; Allow… opens the same window. Prominent buttons in the light theme use a lighter amber, so their text is easier to read. Choose Check for Updates… in Ting to install 0.6.1; your settings, bindings, micro-apps and permissions are kept.'] },
      { title: 'Ting 0.6.0: context and typing', paragraphs: ['A micro-app lists in context: what Ting reads when it starts, and Ting reads only that: app (name, bundle id, path), finder (the selected files and the folder of the front Finder window, also when Finder is in the background), browser (URL and title of the front tab in Safari, Chrome, Arc, Brave, Edge, Vivaldi or Chromium), selection (the selected text) and window (the title and document of the front window). Steps read them as ${context.finder.selection}, code as $TING_CONTEXT_FINDER_SELECTION. New examples: About the active app, Checksum of Finder files, Copy page link, Sort selected lines and Search in a new tab.', 'A keys step presses keys in the app that was in front, such as keys: [cmd+a, return]; a paste step pastes text there; output to: [app] pastes the result. Ting closes its panel first and puts the clipboard back after it pastes. When that app is no longer in front or a password field holds the keyboard, Ting sends nothing. ting-micro run takes values with --context and never sends keys.', 'Ting asks for permissions only when a micro-app needs them: Automation for Finder or the browser (macOS asks once per app), and Accessibility for the selected text, the window, keys, paste and the app output. When an app does not give its selected text through Accessibility, Ting presses Command-C there and puts the clipboard back. Choose Check for Updates… in Ting to install 0.6.0; your settings, bindings and micro-apps are kept.'] },
      { title: 'Ting 0.5.1: faster menu and switching', paragraphs: ['Ting preloads app icons and caches app paths when it loads your bindings, including nested groups. Already running apps are activated directly, before the leader menu hides. The menu view is reused instead of being rebuilt on every opening; its window fits the menu and uses the system shadow.', 'Small keycaps have the same minimum width, with or without a second keyboard-layout letter. Rows for Space and other keys without that letter no longer shift to the left. Choose Check for Updates… in Ting to install 0.5.1; your settings, bindings and micro-apps are kept.'] },
      { title: 'Ting 0.5.0: steps and libraries', paragraphs: ['A micro-app in ~/.config/ting/micro/ can now run a list of steps instead of one command: command (shell), python, url (an HTTP request), ai (OpenAI, Anthropic or any OpenAI-compatible server), text, json, open and notify. The output of each step is the input of the next one. Steps read parameters, earlier outputs, the environment of your login shell and keychain items, so API keys stay out of the files. AI answers and long outputs stream into the panel. Existing micro-apps work as before; a run may take up to 300 seconds if the file sets timeout.', 'Steps shared by several micro-apps live once in ~/.config/ting/micro/libs/. A micro-app runs a library with call, or inherits it with inherit and changes only some values, for example one translate micro-app per language. When a library changes, Ting asks you to approve again every micro-app that uses it.', 'Ting.app/Contents/MacOS/ting-micro checks micro-apps (check), runs one in the terminal without panels or the clipboard (run), and checks config.json (check-config). The new guide CONFIGURING.md inside Ting.app tells Claude Code, Codex or pi how to add micro-apps, key bindings and settings; Copy Agent Prompt now points to it. Ask in plain words, for example “Leader t a should translate the clipboard into German”. A notify step asks for permission to show notifications the first time.'] },
      { title: 'Ting 0.4.0: micro-apps', paragraphs: ['A micro-app is a small tool that runs one shell command. Each one is a YAML file in ~/.config/ting/micro/, in the format of FORMAT.md, which ships inside Ting.app and holds five working examples: Format JSON, Change case, Encode / decode, Count words and DNS lookup. Ting has no editor for them and installs none, so the folder starts empty. Bind a key in Settings › Bindings with + › Micro-app, or start a micro-app by name from launcha.', 'Before the first run, and after any change of the file, the approval panel shows the name, the file and the full command: Command-Return approves, Esc refuses. Then a parameter panel asks for the values and remembers them, and the result panel shows the output as markdown, console text with colours, plain text or code, or copies it. A failing command always shows its error. A file with a mistake is not used: the menu-bar menu warns, Settings › Advanced lists the errors, and micro-errors.log next to the config file holds them.', 'Copy Agent Prompt, in the menu-bar menu and in Settings › Advanced, copies a ready text for a coding agent such as Claude Code, Codex or pi; add what the micro-app should do and paste it. The agent writes and checks the file with Ting --check, which opens no window, reads no config and writes no file, and does not change config.json: you approve the file at its first start and bind its key yourself. Choose Check for Updates… in Ting to install it.'] },
      { title: 'Ting 0.3.3', paragraphs: ['The “ting” that plays when Ting opens an app, link or file is now half as loud. Its switch in Settings → General → System is now called Play a “ting” when opening an app, link or file; turn it off to open things silently. The config key is still playSound. Choose Check for Updates… in Ting to install it.'] },
      { title: 'Ting 0.3.2', paragraphs: ['launcha now indexes every app in its app folders. The index no longer stops at a time, entry or folder-depth limit, and the scan-limit notices are gone. Folder-access prompts and real access errors still appear. Choose Check for Updates… in Ting to install it.'] },
      { title: 'Ting 0.3.1', paragraphs: ['This update reduces the space between selecta’s amber top rule and the leader-key row when the panel title is hidden. It now matches launcha. Choose Check for Updates… in Ting to install it.'] },
      { title: 'launcha — Ting 0.3.0', paragraphs: ['Ting 0.3.0 adds launcha alongside the fixed-sequence menu, selecta. Double-tap the leader to search apps, or assign a separate hotkey in Settings; none is assigned by default. Apps come from /Applications, /System/Applications (including Utilities), ~/Applications and, after consent, ~/Desktop. Matches sort by successful Ting opens and activations over the last seven days, then the most recent one. Ting does not track launches outside Ting. The app index scans at startup and each time launcha opens; while it stays open, background scans run at most once per minute.', 'When no app matches a non-empty query, Spotlight searches indexed files in your home folder, excluding hidden paths, ~/Library and app bundles. Desktop, Documents and Downloads are skipped until you explicitly allow access; macOS may then request folder permissions. No Accessibility or Input Monitoring permission is needed. Use arrow keys to select, Return to open, Command-Return to reveal in Finder and Escape to close.', 'Show panel title applies to both panels. With it off, launcha starts with a compact search field and two tuning forks inside at the right; results remain a list. Usage and the folder-access choice stay local in ~/Library/Application Support/Ting/launcha-history.json and launcha-consent.json, separate from config. To remove this new data when uninstalling, also delete ~/Library/Application Support/Ting/.'] },
      { title: 'Report a problem safely', paragraphs: ['Use https://github.com/bobuk-io/ting/issues for support. Include macOS and Ting versions, steps to reproduce, and the expected result. Do not post private URLs or tokens from your config.', 'Report security issues privately at https://github.com/bobuk-io/ting/security/advisories/new; see SECURITY.md in the repository.'] },
      { title: 'Uninstall and remove data', paragraphs: [], items: ['Turn off launch at login first if it is enabled.', 'Quit Ting and delete /Applications/Ting.app.', 'Optionally delete ~/.config/ting/ for settings, bindings, micro-apps and their error log, and ~/Library/Application Support/Ting/ for usage history, the folder-access choice, micro-app approvals and remembered values.'] },
    ],
    privacyTitle: 'Your shortcuts. On your Mac.', privacyIntro: 'How the GitHub-distributed version of Ting handles settings, links, micro-apps, and updates.',
    privacy: [
      { title: 'Local settings', paragraphs: ['No accounts, analytics, or project servers. Settings and bindings stay in the local JSON file at ~/.config/ting/config.json. Launch at login uses the macOS login item service. launcha keeps successful Ting launch times and the folder-access choice separately in ~/Library/Application Support/Ting/launcha-history.json and launcha-consent.json. It does not track launches outside Ting.', 'Micro-apps are your files in ~/.config/ting/micro/; micro-errors.log next to the config file lists their mistakes. Ting stores the SHA-256 of each approved file in ~/Library/Application Support/Ting/micro-approvals.json and the last parameter values of each micro-app as plain text in micro-values.json there, unless the file says remember: false. Do not type secrets into a remembered micro-app.'] },
      { title: 'Micro-app commands', paragraphs: ['Ting runs shell commands only from micro-app files you approved in the approval panel, and asks again after any change of the file. The command runs with /bin/sh -c as your user, with your full rights and the PATH of your login shell. Ting puts no limit on what it does: there is no sandbox, it can read and change your files, use the network and start other programs; only the run time is limited (60 seconds by default, at most 300). Parameters reach it only as TING_* environment variables and the clipboard only as stdin. The context a file lists (the active app, the Finder selection, the browser tab, the selected text, the front window) reaches code as TING_CONTEXT_* variables; Ting reads nothing a file does not list. keys and paste steps and the app output send key presses and text to the app that was in front. The same applies to python steps; url and ai steps send what the file says to the server it names, with keys from your environment or keychain. A micro-app is approved together with the libraries it uses. Approve only commands you understand.', 'Anyone who can write the micro-apps folder can offer a command; the approval stands between that file and a run. Keep the micro-apps folder, config.json and ~/Library/Application Support/Ting/ writable only by your user account. App and URL bindings run no commands and pass no arguments to apps.'] },
      { title: 'Permissions', paragraphs: ['Ting uses the standard macOS hotkey API for its leader and never requests Input Monitoring permission. It asks for Accessibility only when a micro-app reads the selected text or the front window, presses keys or pastes into an app, and for Automation of Finder or a browser only when a micro-app reads the Finder selection or the browser tab. To read selected text that an app does not give through Accessibility, Ting presses Command-C in that app and puts the clipboard back. launcha scans app folders at startup and on opening; background scans while open run at most once per minute. Spotlight searches indexed home files only for a non-empty query with no app matches. Hidden paths, ~/Library and app bundles are excluded. Desktop, Documents and Downloads require your explicit consent, then may prompt for macOS folder access.'] },
      { title: 'Network use', paragraphs: ['Apart from what your approved micro-apps do (their commands and their url and ai steps), Ting’s only network access is Sparkle: it checks the update feed at https://bobuk.io/apps/ting/appcast.xml (Ting 0.6.1 and older: the public GitHub release feed) and downloads updates from GitHub. The bobuk.io server sees ordinary request data of each check, including your IP address; GitHub may process the same for downloads under its privacy policy. Turn automatic checks off in Settings › General to check only when you choose.', 'Ting opens the URLs you configure using the system default app. The destination service’s privacy policy applies. Copy Agent Prompt, Ting --check and ting-micro check send nothing. Downloads and support are hosted on GitHub; this website is hosted at bobuk.io, with a copy on GitHub Pages.'] },
      { title: 'Deleting data', paragraphs: ['Turn off launch at login, quit Ting, and delete /Applications/Ting.app. To remove settings, bindings and micro-apps too, delete ~/.config/ting/. Delete ~/Library/Application Support/Ting/ to remove launcha history, the folder-access choice, micro-app approvals and remembered values.'] },
      { title: 'Privacy and security questions', paragraphs: ['Use Support for questions. Public issues must not contain private URLs or tokens. For sensitive security reports, use https://github.com/bobuk-io/ting/security/advisories/new as described in SECURITY.md.'] },
    ],
  },
  ru: {
    guide: guides.ru,
    category: 'Для клавиатуры', tagline: 'Нужное приложение. Несколькими клавишами.',
    shots: [
      { ...selecta, caption: 'Ведущая клавиша, затем ещё одна.', alt: 'Меню selecta в Ting, тёмная тема: клавиши для Terminal, Safari, Notes, Calendar, Music, ссылка Home scenes и группы Web и Tools. На каждой клавише — латинская буква и буква текущей раскладки.' },
      { ...launcha, caption: 'Двойное нажатие — поиск приложений.', alt: 'Поиск launcha в Ting: по запросу «system» найдены System Information и System Settings.' },
      { ...light, caption: 'Светлая или тёмная тема — на выбор.', alt: 'Меню selecta в Ting в светлой теме.' },
      { ...bindings, caption: 'Все последовательности — в одной таблице.', alt: 'Настройки Ting, вкладка Bindings: таблица последовательностей клавиш, названий и действий, включая группы Web и Tools.' },
    ],
    description: 'Лаунчер для macOS с ведущей клавишей. Нажмите её, затем одну клавишу или короткую последовательность — откроется приложение или URL либо запустится небольшое микро-приложение. Home, затем w, g — и вы на GitHub. Двойное нажатие ведущей клавиши открывает поиск приложений launcha.',
    features: [
      { title: 'Ting 0.7.0: калькулятор в launcha', text: 'Наберите цифры и оператор, например 2*(3+4), 1,5 × 4 или 200 + 15%: результат появится в launcha первым, а Return скопирует его. Ting считает сам, в десятичных числах, поэтому 0.1 + 0.2 даёт 0.3. Выключается переключателем Calculate in launcha в Settings. Обновления теперь проверяются на bobuk.io.' },
      { title: 'Ting 0.6.1: окно универсального доступа', text: 'Если микро-приложению нужен универсальный доступ, а у Ting его нет, вместо ошибки открывается окно: кнопка Open Accessibility Settings ведёт в нужный раздел системных настроек, а иконку Ting из окна можно перетащить прямо в список приложений. Когда доступ включён, окно закрывается само. Состояние видно в Settings › Advanced.' },
      { title: 'Ting 0.6.0: контекст и ввод', text: 'Микро-приложение может узнать, с чем вы работали: активное приложение, выделенные в Finder файлы, вкладку браузера, выделенный текст и переднее окно — но только то, что перечислено в context: его файла. Шаги keys и paste нажимают клавиши и вставляют текст в приложение, из которого вы пришли, а output to: [app] ставит результат на место выделения. Панель одобрения показывает, что микро-приложение читает и отправляет.' },
      { title: 'Ting 0.5.1: быстрее меню и переключение', text: 'При загрузке привязок Ting заранее загружает иконки и кеширует пути приложений. Уже запущенные приложения активируются напрямую, до скрытия меню. Представление меню используется повторно, окно соответствует размеру содержимого и использует системную тень. Пробел и другие клавиши без подсказки раскладки теперь имеют ту же минимальную ширину, поэтому строки выровнены.' },
      { title: 'Ting 0.5.0: шаги и библиотеки', text: 'Теперь микро-приложение может быть списком шагов: код оболочки или Python, HTTP-запросы, обращения к ИИ (OpenAI, Anthropic или локальный сервер, например Ollama), текст, поля JSON, открытие URL и уведомления. Вывод каждого шага идёт на вход следующему. Общие шаги хранятся один раз в библиотеках. Консольная утилита ting-micro проверяет и запускает микро-приложения, а агент теперь может добавлять и ваши привязки.' },
      { title: 'Ting 0.4.0: микро-приложения', text: 'Микро-приложение — это один YAML-файл, который запускает одну команду оболочки: он может спросить несколько параметров, прочитать текст из буфера обмена и показать или скопировать результат. Привяжите к нему клавишу или запустите из launcha. Ting выполняет его только после того, как вы одобрите именно этот файл. Copy Agent Prompt даёт Claude Code, Codex или pi всё нужное, чтобы написать такой файл, а Ting --check его проверяет.' },
      { title: 'Ting 0.3.3: тише «ting»', text: 'Звук при открытии приложения, ссылки или файла теперь вдвое тише. Выключить его можно в Settings → General переключателем Play a “ting” when opening an app, link or file.' },
      { title: 'Ting 0.3.2: полный список приложений', text: 'launcha сканирует все приложения в своих папках, какой бы большой или глубокой ни была вложенность, и больше не показывает подписи о лимитах.' },
      { title: 'Ting 0.3.1: меньше отступ selecta', text: 'Когда заголовок панели скрыт, строка ведущей клавиши расположена ближе к янтарной полосе, как в launcha.' },
      { title: 'Новое в 0.3.0: launcha', text: 'Дважды нажмите ведущую клавишу для поиска приложений или назначьте отдельный хоткей. Результаты сортируются по успешным запускам через Ting за семь дней. Если приложений нет, Spotlight ищет индексированные файлы дома с учётом согласия на доступ к папкам. Для обновления выберите Check for Updates… в Ting.' },
      { title: 'Одна клавиша для начала', text: 'Выберите любую клавишу, кроме модификатора, отдельно или в сочетании: Home, F13 или Option-Shift-Command-F. Один модификатор не подойдёт. Ведущей клавиши по умолчанию нет: Ting предложит выбрать её при первом запуске.' },
      { title: 'Меню, когда оно нужно', text: 'Собирайте вложенные группы, например Apps и Web. Используйте буквы, цифры, Space, Return и F-клавиши. Esc закрывает меню, Delete возвращает на уровень назад. При быстром наборе меню не появляется: задержка по умолчанию — 0.25 с.' },
      { title: 'Раскладку можно не менять', text: 'Привязки сохраняются по латинской букве клавиши и работают с любой раскладкой, в том числе русской и украинской. Рядом с латинской буквой меню показывает небольшую подсказку для текущей раскладки.' },
      { title: 'Ваши привязки в одном файле', text: 'Редактируйте ~/.config/ting/config.json вручную, храните в dotfiles или пользуйтесь Settings. Ting подхватывает изменения сам. Приложения запускаются или выходят на передний план, URL открываются стандартным обработчиком — в том числе схемы вроде raycast://.' },
    ],
    installNote: 'Универсальный ZIP для Apple Silicon и Intel с файлом контрольной суммы SHA-256. Приложение живёт в строке меню, без значка в Dock. Интерфейс только на английском.',
    steps: [
      { title: 'Скачайте и установите', text: 'Скачайте ZIP последнего релиза на GitHub, распакуйте и перенесите Ting.app в /Applications. Релизы подписаны Developer ID и нотарифицированы Apple.' },
      { title: 'Выберите ведущую клавишу', text: 'Откройте Ting и нажмите клавишу, с которой хотите начинать последовательности. Для ведущей клавиши разрешения на универсальный доступ и мониторинг ввода не нужны: Ting использует стандартный API горячих клавиш macOS.' },
      { title: 'Настройте под себя', text: 'В Settings → Bindings запишите последовательности клавиш и завершите запись кнопкой Done. Недостающие группы создаются, пустые удаляются автоматически. Можно редактировать ~/.config/ting/config.json напрямую.' },
    ],
    faq: [
      { question: 'Нужны специальные разрешения?', answer: 'Для ведущей клавиши и launcha универсальный доступ и мониторинг ввода не нужны. С 0.6.0 микро-приложению, которое читает выделенный текст или переднее окно, нажимает клавиши или вставляет текст в приложение, нужен универсальный доступ, а тому, что читает выделение в Finder или вкладку браузера, — автоматизация для этого приложения; Ting спрашивает только тогда. С 0.6.1 без универсального доступа Ting открывает окно, которое показывает, как его включить. launcha пропускает Desktop, Documents и Downloads до вашего явного согласия; затем macOS может запросить доступ к папкам.' },
      { question: 'Можно запускать команды оболочки?', answer: 'Да, через микро-приложения начиная с 0.4.0: это YAML-файлы в ~/.config/ting/micro/. Ting выполняет команду только после того, как вы одобрите именно это содержимое файла, от вашего имени и со всеми вашими правами, по умолчанию не дольше 60 секунд и максимум 300. С 0.5.0 микро-приложение может выполнять и Python, HTTP-запросы и обращения к ИИ в виде шагов, а с 0.6.0 — узнать активное приложение, выделение в Finder, вкладку браузера или выделенный текст и вставить результат в приложение. Привязки к приложениям и URL команд не запускают; в config.json нет кода.' },
      { question: 'Работает с русской и украинской раскладками?', answer: 'Да. Привязки хранятся по латинской букве клавиши, а меню подсказывает букву текущей раскладки. Переключать раскладку не нужно.' },
      { question: 'Чем отличается от Spotlight?', answer: 'selecta открывает ваши постоянные последовательности без поиска. При быстром наборе меню не появляется. launcha ищет приложения по имени и сортирует их по использованию через Ting. Поиск файлов Spotlight включается, только если приложений нет. С 0.7.0 launcha ещё и считает: наберите 2*(3+4) и нажмите Return, чтобы скопировать 14.' },
      { question: 'Есть в App Store?', answer: 'Нет. Универсальный ZIP доступен в GitHub Releases. Встроенные обновления через Sparkle читают ленту на bobuk.io (Ting 0.6.1 и старше — ленту релизов GitHub) и скачивают релизы с GitHub.' },
      { question: 'Почему Ting?', answer: '«Ting» — «штука» на ямайском патуа и лондонском сленге. Янтарные клавиши, графитовая панель и подсказки «pull up» / «rewind» слегка отсылают к грайму и культуре саунд-систем.' },
    ],
    supportIntro: 'Ведущая клавиша, привязки и помощь проекта. Не публикуйте приватные URL и токены из конфигурации.',
    support: [
      { title: 'Клавиша или последовательность не срабатывает?', paragraphs: [], items: ['Выберите клавишу, отличную от модификатора, при желании — в сочетании с модификаторами. Один Right Option не подойдёт, а Home или F13 подойдут.', 'Проверьте последовательность в Settings → Bindings. Завершите запись кнопкой Done. Esc закрывает меню, Delete возвращает на одну группу назад.', 'Проверьте задержку меню и поведение при неизвестной клавише в General. По умолчанию задержка — 0.25 с: быстрая последовательность может завершиться раньше, чем появится меню.'] },
      { title: 'Настройки и конфигурация', paragraphs: ['В General находятся тема Light/Dark (по умолчанию тёмная), ведущая клавиша, задержка меню, поведение при неизвестной клавише, запуск при входе, значок в строке меню и звук. Show panel title позволяет скрыть строку Ting · selecta, оставив видимыми камертон ведущей клавиши и последовательность. В Advanced — путь к конфигурации, показ файла, перезагрузка, импорт и экспорт, а также папка микро-приложений: найденные микро-приложения, их ошибки, Open Folder in Finder и Copy Agent Prompt.', 'Настройки и привязки хранятся в ~/.config/ting/config.json. Ting подхватывает изменения; если в файле ошибка, сохраняет последние исправные настройки и показывает ошибку в меню.'] },
      { title: 'Ting 0.7.0: калькулятор в launcha', paragraphs: ['Запрос из цифр и оператора, например 2*(3+4), 1,5 × 4, 200 + 15%, 2^10 или sqrt(2), показывает результат первым, выше приложений и файлов; Return копирует его, и Ting пишет Copied. Десятичный разделитель — точка или запятая. Работают + - * / ^, × ÷, скобки, mod, проценты (200 + 15% даёт 230), pi, e и функции sqrt, abs, round, floor, ceil, ln, log, exp, sin, cos и tan (в радианах); в результате остаётся до 12 знаков после точки. Одиночное число, версия вида 1.2.3 или деление на ноль результата не дают. Калькулятор включён по умолчанию: выключите его переключателем Calculate in launcha в Settings › General или ключом "calculator": false в разделе launcha файла config.json.', 'Sparkle теперь проверяет обновления по адресу https://bobuk.io/apps/ting/appcast.xml, поэтому новый релиз виден сразу после публикации; архивы по-прежнему скачиваются из GitHub Releases и принимаются только с подписью Ting. Ting 0.6.1 и старше найдут 0.7.0 через ленту GitHub. Чтобы установить 0.7.0, выберите Check for Updates… в Ting. Настройки, привязки, микро-приложения и разрешения сохранятся.'] },
      { title: 'Ting 0.6.1: окно универсального доступа', paragraphs: ['Если микро-приложению нужен универсальный доступ (выделенный текст, переднее окно, keys, paste или output to: [app]), а у Ting его нет, Ting открывает окно с шагами вместо панели с ошибкой или системного запроса macOS. Кнопка Open Accessibility Settings открывает раздел универсального доступа в настройках конфиденциальности и безопасности; перетащите иконку Ting из окна в список приложений или нажмите + и выберите Ting, затем включите переключатель. Окно остаётся поверх системных настроек и закрывается само, когда доступ включён; после этого запустите микро-приложение снова. Результат, который не удалось вставить, остаётся в буфере обмена.', 'Settings › Advanced показывает, есть ли у Ting универсальный доступ; кнопка Allow… открывает то же окно. Заметные кнопки в светлой теме теперь светло-янтарные, их текст легче читать. Чтобы установить 0.6.1, выберите Check for Updates… в Ting. Настройки, привязки, микро-приложения и разрешения сохранятся.'] },
      { title: 'Ting 0.6.0: контекст и ввод', paragraphs: ['Микро-приложение перечисляет в context: то, что Ting читает при запуске, и Ting читает только это: app (имя, bundle id, путь), finder (выделенные файлы и папка переднего окна Finder, даже если Finder в фоне), browser (URL и заголовок передней вкладки в Safari, Chrome, Arc, Brave, Edge, Vivaldi или Chromium), selection (выделенный текст) и window (заголовок и документ переднего окна). Шаги читают их как ${context.finder.selection}, код — как $TING_CONTEXT_FINDER_SELECTION. Новые примеры: About the active app, Checksum of Finder files, Copy page link, Sort selected lines и Search in a new tab.', 'Шаг keys нажимает клавиши в приложении, которое было впереди, например keys: [cmd+a, return]; шаг paste вставляет туда текст; output to: [app] вставляет результат. Сначала Ting закрывает свою панель, а после вставки возвращает прежний буфер обмена. Если то приложение уже не впереди или клавиатуру держит поле пароля, Ting ничего не отправляет. ting-micro run принимает значения через --context и никогда не отправляет клавиши.', 'Ting запрашивает разрешения, только когда они нужны микро-приложению: автоматизацию для Finder или браузера (macOS спрашивает один раз для каждого приложения) и универсальный доступ для выделенного текста, окна, keys, paste и вывода в приложение. Если приложение не отдаёт выделенный текст через универсальный доступ, Ting нажимает в нём Command-C и возвращает буфер обмена. Чтобы установить 0.6.0, выберите Check for Updates… в Ting. Настройки, привязки и микро-приложения сохранятся.'] },
      { title: 'Ting 0.5.1: быстрее меню и переключение', paragraphs: ['При загрузке привязок, включая вложенные группы, Ting заранее загружает иконки и кеширует пути приложений. Уже запущенные приложения активируются напрямую, до скрытия меню ведущей клавиши. Представление меню используется повторно, а не создаётся заново при каждом открытии; окно соответствует размеру меню и использует системную тень.', 'Маленькие клавиши имеют одинаковую минимальную ширину, со второй буквой раскладки или без неё. Строки пробела и других клавиш без этой буквы больше не сдвигаются влево. Чтобы установить 0.5.1, выберите Check for Updates… в Ting. Настройки, привязки и микро-приложения сохранятся.'] },
      { title: 'Ting 0.5.0: шаги и библиотеки', paragraphs: ['Микро-приложение в ~/.config/ting/micro/ теперь может выполнять список шагов вместо одной команды: command (оболочка), python, url (HTTP-запрос), ai (OpenAI, Anthropic или любой OpenAI-совместимый сервер), text, json, open и notify. Вывод каждого шага идёт на вход следующему. Шаги читают параметры, вывод предыдущих шагов, окружение вашей оболочки входа и записи связки ключей, поэтому API-ключи не попадают в файлы. Ответы ИИ и длинный вывод появляются в панели по мере поступления. Старые микро-приложения работают как раньше; если в файле указан timeout, запуск может длиться до 300 секунд.', 'Шаги, общие для нескольких микро-приложений, хранятся один раз в ~/.config/ting/micro/libs/. Микро-приложение запускает библиотеку через call или наследует её через inherit и меняет только часть значений, например одно микро-приложение перевода на каждый язык. После изменения библиотеки Ting снова просит одобрить каждое микро-приложение, которое её использует.', 'Ting.app/Contents/MacOS/ting-micro проверяет микро-приложения (check), запускает их в терминале без панелей и буфера обмена (run) и проверяет config.json (check-config). Новое руководство CONFIGURING.md внутри Ting.app объясняет Claude Code, Codex или pi, как добавлять микро-приложения, привязки клавиш и настройки; Copy Agent Prompt теперь ведёт к нему. Просите обычными словами, например «Leader t a должен переводить буфер обмена на немецкий». Шаг notify при первом уведомлении спрашивает разрешение на уведомления.'] },
      { title: 'Ting 0.4.0: микро-приложения', paragraphs: ['Микро-приложение — небольшой инструмент, который запускает одну команду оболочки. Каждое — это YAML-файл в ~/.config/ting/micro/ в формате FORMAT.md. Этот документ лежит внутри Ting.app и содержит пять рабочих примеров: Format JSON, Change case, Encode / decode, Count words и DNS lookup. Редактора для них в Ting нет, и сам он ничего не устанавливает, поэтому папка сначала пуста. Привяжите клавишу в Settings › Bindings через + › Micro-app или запустите микро-приложение по имени из launcha.', 'Перед первым запуском и после любого изменения файла панель одобрения показывает название, файл и полную команду: Command-Return одобряет, Esc отказывает. Затем панель параметров спрашивает значения и запоминает их, а панель результата показывает вывод как markdown, консольный текст с цветами, простой текст или код либо копирует его. Ошибку команды Ting показывает всегда. Файл с ошибкой не используется: меню в строке меню предупреждает, Settings › Advanced перечисляет ошибки, а micro-errors.log рядом с файлом конфигурации хранит их.', 'Copy Agent Prompt в меню строки меню и в Settings › Advanced копирует готовый текст для агента, например Claude Code, Codex или pi; допишите, что должно делать микро-приложение, и вставьте текст. Агент пишет файл и проверяет его командой Ting --check, которая не открывает окон, не читает конфигурацию и ничего не записывает, и не меняет config.json: файл вы одобряете при первом запуске и клавишу назначаете сами. Выберите Check for Updates… в Ting, чтобы установить обновление.'] },
      { title: 'Ting 0.3.3', paragraphs: ['Звук «ting» при открытии приложения, ссылки или файла теперь вдвое тише. Его переключатель в Settings → General → System теперь называется Play a “ting” when opening an app, link or file; выключите его, чтобы всё открывалось без звука. Ключ в конфигурации по-прежнему playSound. Выберите Check for Updates… в Ting, чтобы установить обновление.'] },
      { title: 'Ting 0.3.2', paragraphs: ['launcha индексирует все приложения в своих папках. Индекс больше не останавливается по лимиту времени, числа записей или глубины папок, подписи о лимитах убраны. Запросы доступа к папкам и настоящие ошибки доступа по-прежнему показываются. Выберите Check for Updates… в Ting, чтобы установить обновление.'] },
      { title: 'Ting 0.3.1', paragraphs: ['В этом обновлении уменьшен отступ между янтарной полосой и строкой ведущей клавиши в selecta без заголовка. Теперь он такой же, как в launcha. Выберите Check for Updates… в Ting, чтобы установить обновление.'] },
      { title: 'launcha — Ting 0.3.0', paragraphs: ['Ting 0.3.0 добавляет launcha рядом с меню фиксированных последовательностей selecta. Дважды нажмите ведущую клавишу для поиска приложений или назначьте отдельный хоткей в Settings; по умолчанию он не назначен. Приложения берутся из /Applications, /System/Applications (включая Utilities), ~/Applications и, после согласия, ~/Desktop. Совпадения сортируются по числу успешных запусков и активаций через Ting за последние семь дней, затем по дате последнего действия. Запуски вне Ting не учитываются. Индекс приложений обновляется при запуске Ting и открытии launcha. Пока панель открыта, фоновое сканирование выполняется не чаще раза в минуту.', 'Если по непустому запросу нет приложений, Spotlight ищет индексированные файлы в домашней папке, исключая скрытые пути, ~/Library и пакеты приложений. Desktop, Documents и Downloads пропускаются до вашего явного согласия; затем macOS может запросить доступ к папкам. Универсальный доступ и мониторинг ввода не нужны. Стрелки выбирают результат, Return открывает, Command-Return показывает в Finder, Escape закрывает.', 'Show panel title действует на обе панели. Без заголовка launcha начинается с компактного поля поиска с двумя камертонами внутри справа; результаты остаются списком. История и выбор доступа остаются локально в ~/Library/Application Support/Ting/launcha-history.json и launcha-consent.json, отдельно от конфигурации. Чтобы удалить эти новые данные при удалении приложения, удалите также ~/Library/Application Support/Ting/.'] },
      { title: 'Как безопасно сообщить о проблеме', paragraphs: ['Для поддержки используйте https://github.com/bobuk-io/ting/issues. Укажите версии macOS и Ting, шаги воспроизведения и ожидаемый результат. Не публикуйте приватные URL и токены из конфигурации.', 'Об уязвимостях сообщайте приватно: https://github.com/bobuk-io/ting/security/advisories/new. Подробности — в SECURITY.md репозитория.'] },
      { title: 'Удаление приложения и данных', paragraphs: [], items: ['Если включён запуск при входе, сначала отключите его.', 'Закройте Ting и удалите /Applications/Ting.app.', 'При желании удалите ~/.config/ting/ для настроек, привязок, микро-приложений и их журнала ошибок и ~/Library/Application Support/Ting/ для истории, выбора доступа к папкам, одобрений микро-приложений и запомненных значений.'] },
    ],
    privacyTitle: 'Ваши сочетания. На вашем Mac.', privacyIntro: 'Как версия Ting с GitHub обрабатывает настройки, ссылки, микро-приложения и обновления.',
    privacy: [
      { title: 'Локальные настройки', paragraphs: ['Без аккаунтов, аналитики и серверов проекта. Настройки и привязки остаются в локальном JSON-файле ~/.config/ting/config.json. Запуск при входе использует системную службу объектов входа macOS. launcha хранит время успешных запусков через Ting и выбор доступа отдельно в ~/Library/Application Support/Ting/launcha-history.json и launcha-consent.json. Запуски вне Ting не отслеживаются.', 'Микро-приложения — это ваши файлы в ~/.config/ting/micro/; micro-errors.log рядом с файлом конфигурации перечисляет их ошибки. Ting хранит SHA-256 каждого одобренного файла в ~/Library/Application Support/Ting/micro-approvals.json, а последние значения параметров каждого микро-приложения — обычным текстом в micro-values.json там же, если в файле не указано remember: false. Не вводите секреты в микро-приложение, которое запоминает значения.'] },
      { title: 'Команды микро-приложений', paragraphs: ['Ting запускает команды оболочки только из файлов микро-приложений, которые вы одобрили в панели одобрения, и спрашивает снова после любого изменения файла. Команда выполняется через /bin/sh -c от вашего имени, со всеми вашими правами и с PATH вашей оболочки входа. Ting никак не ограничивает её действия: песочницы нет, команда может читать и менять ваши файлы, работать с сетью и запускать другие программы; ограничено только время работы: по умолчанию 60 секунд, максимум 300. Параметры попадают в неё только как переменные окружения TING_*, а буфер обмена — только через stdin. Контекст, перечисленный в файле (активное приложение, выделение в Finder, вкладка браузера, выделенный текст, переднее окно), попадает в код как переменные TING_CONTEXT_*; то, чего нет в файле, Ting не читает. Шаги keys и paste и вывод в приложение отправляют нажатия клавиш и текст в приложение, которое было впереди. То же относится к шагам python; шаги url и ai отправляют то, что указано в файле, на указанный там сервер, с ключами из вашего окружения или связки ключей. Микро-приложение одобряется вместе с библиотеками, которые оно использует. Одобряйте только понятные вам команды.', 'Кто может писать в папку микро-приложений, тот может предложить команду; между таким файлом и запуском стоит ваше одобрение. Папка микро-приложений, config.json и ~/Library/Application Support/Ting/ должны быть доступны на запись только вашей учётной записи. Привязки к приложениям и URL команд не запускают и аргументов приложениям не передают.'] },
      { title: 'Разрешения', paragraphs: ['Для ведущей клавиши Ting использует стандартный API горячих клавиш macOS и никогда не запрашивает мониторинг ввода. Универсальный доступ он запрашивает, только когда микро-приложение читает выделенный текст или переднее окно, нажимает клавиши или вставляет текст в приложение, а автоматизацию Finder или браузера — только когда микро-приложение читает выделение в Finder или вкладку браузера. Чтобы прочитать выделенный текст, который приложение не отдаёт через универсальный доступ, Ting нажимает в нём Command-C и возвращает буфер обмена. launcha сканирует папки приложений при запуске и открытии панели; фоновое сканирование открытой панели — не чаще раза в минуту. Spotlight ищет индексированные файлы дома только по непустому запросу без совпадений приложений. Скрытые пути, ~/Library и пакеты приложений исключены. Для Desktop, Documents и Downloads нужно ваше явное согласие; затем macOS может запросить доступ к папкам.'] },
      { title: 'Когда используется сеть', paragraphs: ['Кроме того, что делают одобренные вами микро-приложения (их команды и шаги url и ai), Ting обращается к сети только через Sparkle: он проверяет ленту обновлений https://bobuk.io/apps/ting/appcast.xml (Ting 0.6.1 и старше — публичную ленту релизов GitHub) и скачивает обновления с GitHub. Сервер bobuk.io видит обычные данные каждой проверки, включая IP-адрес; GitHub может обрабатывать такие же данные при скачивании по своей политике конфиденциальности. Чтобы проверять обновления только по своему желанию, выключите автоматическую проверку в Settings › General.', 'Ting открывает указанные вами URL стандартным приложением системы. Действует политика соответствующего сервиса. Copy Agent Prompt, Ting --check и ting-micro check ничего не отправляют. Загрузки и поддержка размещены на GitHub, этот сайт — на bobuk.io, его копия — на GitHub Pages.'] },
      { title: 'Как удалить данные', paragraphs: ['Отключите запуск при входе, закройте Ting и удалите /Applications/Ting.app. Чтобы стереть настройки, привязки и микро-приложения, удалите также ~/.config/ting/. Для истории launcha, выбора доступа к папкам, одобрений микро-приложений и запомненных значений удалите ~/Library/Application Support/Ting/.'] },
      { title: 'Вопросы о данных и безопасности', paragraphs: ['С вопросами обращайтесь в поддержку. Не включайте приватные URL и токены в публичные issue. Для чувствительных сообщений об уязвимостях используйте https://github.com/bobuk-io/ting/security/advisories/new по инструкции SECURITY.md.'] },
    ],
  },
  uk: {
    guide: guides.uk,
    category: 'Для клавіатури', tagline: 'Потрібний застосунок. Кількома клавішами.',
    shots: [
      { ...selecta, caption: 'Початкова клавіша, потім ще одна.', alt: 'Меню selecta в Ting, темна тема: клавіші для Terminal, Safari, Notes, Calendar, Music, посилання Home scenes і групи Web та Tools. На кожній клавіші — латинська літера й літера поточної розкладки.' },
      { ...launcha, caption: 'Подвійне натискання — пошук застосунків.', alt: 'Пошук launcha в Ting: за запитом «system» знайдено System Information і System Settings.' },
      { ...light, caption: 'Світла чи темна тема — на вибір.', alt: 'Меню selecta в Ting у світлій темі.' },
      { ...bindings, caption: 'Усі послідовності — в одній таблиці.', alt: 'Налаштування Ting, вкладка Bindings: таблиця послідовностей клавіш, назв і дій, зокрема групи Web та Tools.' },
    ],
    description: 'Лаунчер для macOS із початковою клавішею. Натисніть її, а потім одну клавішу чи коротку послідовність — відкриється застосунок або URL чи запуститься невеликий мікрозастосунок. Home, потім w, g — і ви на GitHub. Подвійне натискання початкової клавіші відкриває пошук застосунків launcha.',
    features: [
      { title: 'Ting 0.7.0: калькулятор у launcha', text: 'Наберіть цифри й оператор, наприклад 2*(3+4), 1,5 × 4 або 200 + 15%: результат з’явиться в launcha першим, а Return скопіює його. Ting рахує сам, у десяткових числах, тож 0.1 + 0.2 дає 0.3. Вимикається перемикачем Calculate in launcha в Settings. Оновлення тепер перевіряються на bobuk.io.' },
      { title: 'Ting 0.6.1: вікно доступності', text: 'Якщо мікрозастосунку потрібна доступність, а в Ting її немає, замість помилки відкривається вікно: кнопка Open Accessibility Settings веде до потрібного розділу системних налаштувань, а іконку Ting із вікна можна перетягнути просто в список застосунків. Коли доступ увімкнено, вікно закривається саме. Стан видно в Settings › Advanced.' },
      { title: 'Ting 0.6.0: контекст і введення', text: 'Мікрозастосунок може дізнатися, з чим ви працювали: активний застосунок, виділені у Finder файли, вкладку браузера, виділений текст і переднє вікно — але лише те, що перелічено в context: його файлу. Кроки keys і paste натискають клавіші й вставляють текст у застосунок, з якого ви прийшли, а output to: [app] ставить результат на місце виділення. Панель схвалення показує, що мікрозастосунок читає й надсилає.' },
      { title: 'Ting 0.5.1: швидше меню та перемикання', text: 'Під час завантаження прив’язок Ting заздалегідь завантажує іконки та кешує шляхи застосунків. Уже запущені застосунки активуються напряму, до приховування меню. Подання меню використовується повторно, вікно відповідає розміру вмісту й використовує системну тінь. Пробіл та інші клавіші без підказки розкладки тепер мають ту саму мінімальну ширину, тож рядки вирівняні.' },
      { title: 'Ting 0.5.0: кроки та бібліотеки', text: 'Тепер мікрозастосунок може бути списком кроків: код оболонки або Python, HTTP-запити, звернення до ШІ (OpenAI, Anthropic або локальний сервер, наприклад Ollama), текст, поля JSON, відкриття URL і сповіщення. Вивід кожного кроку йде на вхід наступному. Спільні кроки зберігаються один раз у бібліотеках. Консольна утиліта ting-micro перевіряє й запускає мікрозастосунки, а агент тепер може додавати й ваші прив’язки.' },
      { title: 'Ting 0.4.0: мікрозастосунки', text: 'Мікрозастосунок — це один YAML-файл, що запускає одну команду оболонки: він може запитати кілька параметрів, прочитати текст із буфера обміну й показати чи скопіювати результат. Прив’яжіть до нього клавішу або запустіть із launcha. Ting виконує його лише після того, як ви схвалите саме цей файл. Copy Agent Prompt дає Claude Code, Codex або pi все потрібне, щоб написати такий файл, а Ting --check його перевіряє.' },
      { title: 'Ting 0.3.3: тихіший «ting»', text: 'Звук під час відкриття застосунку, посилання чи файлу тепер удвічі тихіший. Вимкнути його можна в Settings → General перемикачем Play a “ting” when opening an app, link or file.' },
      { title: 'Ting 0.3.2: повний список застосунків', text: 'launcha сканує всі застосунки у своїх папках, якою б великою чи глибокою не була вкладеність, і більше не показує підписи про ліміти.' },
      { title: 'Ting 0.3.1: менший відступ selecta', text: 'Коли заголовок панелі приховано, рядок початкової клавіші розташований ближче до бурштинової смуги, як у launcha.' },
      { title: 'Нове в 0.3.0: launcha', text: 'Двічі натисніть початкову клавішу для пошуку застосунків або призначте окрему гарячу клавішу. Результати сортуються за успішними запусками через Ting за сім днів. Якщо застосунків немає, Spotlight шукає індексовані файли вдома з урахуванням згоди на доступ до папок. Для оновлення виберіть Check for Updates… у Ting.' },
      { title: 'Одна клавіша для початку', text: 'Виберіть будь-яку клавішу, крім модифікатора, окремо або в поєднанні: Home, F13 чи Option-Shift-Command-F. Сам модифікатор не підійде. Початкової клавіші за замовчуванням немає: Ting запропонує вибрати її під час першого запуску.' },
      { title: 'Меню, коли воно потрібне', text: 'Створюйте вкладені групи, наприклад Apps і Web. Використовуйте літери, цифри, Space, Return і F-клавіші. Esc закриває меню, Delete повертає на рівень назад. За швидкого набору меню не з’являється: типова затримка — 0.25 с.' },
      { title: 'Розкладку можна не перемикати', text: 'Прив’язки зберігаються за латинською літерою клавіші й працюють із будь-якою розкладкою, зокрема українською та російською. Поруч із латинською літерою меню показує невелику підказку для поточної розкладки.' },
      { title: 'Ваші прив’язки в одному файлі', text: 'Редагуйте ~/.config/ting/config.json вручну, зберігайте в dotfiles або користуйтеся Settings. Ting підхоплює зміни автоматично. Застосунки запускаються чи виходять на передній план, URL відкриваються типовим обробником — зокрема схеми на кшталт raycast://.' },
    ],
    installNote: 'Універсальний ZIP для Apple Silicon та Intel із файлом контрольної суми SHA-256. Застосунок працює в рядку меню, без значка в Dock. Інтерфейс лише англійською.',
    steps: [
      { title: 'Завантажте та встановіть', text: 'Завантажте ZIP останнього релізу на GitHub, розпакуйте та перенесіть Ting.app у /Applications. Релізи підписані Developer ID та нотаризовані Apple.' },
      { title: 'Виберіть початкову клавішу', text: 'Відкрийте Ting і натисніть клавішу, з якої хочете починати послідовності. Для початкової клавіші дозволи на доступність і моніторинг вводу не потрібні: Ting використовує стандартний API гарячих клавіш macOS.' },
      { title: 'Налаштуйте під себе', text: 'У Settings → Bindings запишіть послідовності клавіш і завершіть запис кнопкою Done. Відсутні групи створюються, порожні видаляються автоматично. Можна також редагувати ~/.config/ting/config.json безпосередньо.' },
    ],
    faq: [
      { question: 'Чи потрібні спеціальні дозволи?', answer: 'Для початкової клавіші й launcha доступність і моніторинг вводу не потрібні. З 0.6.0 мікрозастосунку, який читає виділений текст або переднє вікно, натискає клавіші чи вставляє текст у застосунок, потрібна доступність, а тому, що читає виділення у Finder або вкладку браузера, — автоматизація для цього застосунку; Ting запитує лише тоді. З 0.6.1 без доступності Ting відкриває вікно, яке показує, як її ввімкнути. launcha пропускає Desktop, Documents і Downloads до вашої явної згоди; потім macOS може запитати доступ до папок.' },
      { question: 'Чи можна запускати команди оболонки?', answer: 'Так, через мікрозастосунки, починаючи з 0.4.0: це YAML-файли в ~/.config/ting/micro/. Ting виконує команду лише після того, як ви схвалите саме цей вміст файлу, від вашого імені та з усіма вашими правами, типово не довше 60 секунд і щонайбільше 300. З 0.5.0 мікрозастосунок може виконувати також Python, HTTP-запити й звернення до ШІ у вигляді кроків, а з 0.6.0 — дізнатися активний застосунок, виділення у Finder, вкладку браузера чи виділений текст і вставити результат у застосунок. Прив’язки до застосунків і URL команд не запускають; у config.json немає коду.' },
      { question: 'Працює з українською та російською розкладками?', answer: 'Так. Прив’язки зберігаються за латинською літерою клавіші, а меню підказує літеру поточної розкладки. Перемикати розкладку не потрібно.' },
      { question: 'Чим відрізняється від Spotlight?', answer: 'selecta відкриває ваші сталі послідовності без пошуку. За швидкого набору меню не з’являється. launcha шукає застосунки за назвою та сортує їх за використанням через Ting. Пошук файлів Spotlight вмикається, лише якщо застосунків немає. З 0.7.0 launcha ще й рахує: наберіть 2*(3+4) і натисніть Return, щоб скопіювати 14.' },
      { question: 'Чи є в App Store?', answer: 'Ні. Універсальний ZIP доступний у GitHub Releases. Вбудовані оновлення через Sparkle читають стрічку на bobuk.io (Ting 0.6.1 і старші — стрічку релізів GitHub) і завантажують релізи з GitHub.' },
      { question: 'Чому Ting?', answer: '«Ting» — «штука» ямайською патуа та лондонським сленгом. Бурштинові клавіші, графітова панель і підказки «pull up» / «rewind» злегка відсилають до ґрайму й культури саунд-систем.' },
    ],
    supportIntro: 'Початкова клавіша, прив’язки та допомога проєкту. Не публікуйте приватні URL і токени з конфігурації.',
    support: [
      { title: 'Клавіша чи послідовність не спрацьовує?', paragraphs: [], items: ['Виберіть клавішу, відмінну від модифікатора, за бажанням — разом із модифікаторами. Сам Right Option не підійде, а Home або F13 підійдуть.', 'Перевірте послідовність у Settings → Bindings. Завершіть запис кнопкою Done. Esc закриває меню, Delete повертає на одну групу назад.', 'Перевірте затримку меню та поведінку за невідомої клавіші в General. Типова затримка — 0.25 с: швидка послідовність може завершитися раніше, ніж з’явиться меню.'] },
      { title: 'Налаштування та конфігурація', paragraphs: ['У General розміщені тема Light/Dark (типово темна), початкова клавіша, затримка меню, поведінка за невідомої клавіші, запуск під час входу, значок у рядку меню та звук. Show panel title дає змогу приховати рядок Ting · selecta, залишивши видимими камертон початкової клавіші й послідовність. В Advanced — шлях до конфігурації, показ файлу, перезавантаження, імпорт та експорт, а також папка мікрозастосунків: знайдені мікрозастосунки, їхні помилки, Open Folder in Finder і Copy Agent Prompt.', 'Налаштування та прив’язки зберігаються в ~/.config/ting/config.json. Ting підхоплює зміни; якщо у файлі помилка, залишає останні справні налаштування й показує помилку в меню.'] },
      { title: 'Ting 0.7.0: калькулятор у launcha', paragraphs: ['Запит із цифр і оператора, наприклад 2*(3+4), 1,5 × 4, 200 + 15%, 2^10 або sqrt(2), показує результат першим, вище за застосунки й файли; Return копіює його, і Ting пише Copied. Десятковий роздільник — крапка або кома. Працюють + - * / ^, × ÷, дужки, mod, відсотки (200 + 15% дає 230), pi, e та функції sqrt, abs, round, floor, ceil, ln, log, exp, sin, cos і tan (у радіанах); у результаті лишається до 12 знаків після крапки. Окреме число, версія на кшталт 1.2.3 чи ділення на нуль результату не дають. Калькулятор увімкнено типово: вимкніть його перемикачем Calculate in launcha в Settings › General або ключем "calculator": false у розділі launcha файлу config.json.', 'Sparkle тепер перевіряє оновлення за адресою https://bobuk.io/apps/ting/appcast.xml, тож новий реліз видно одразу після публікації; архіви й далі завантажуються з GitHub Releases і приймаються лише з підписом Ting. Ting 0.6.1 і старші знайдуть 0.7.0 через стрічку GitHub. Щоб установити 0.7.0, виберіть Check for Updates… у Ting. Налаштування, прив’язки, мікрозастосунки та дозволи збережуться.'] },
      { title: 'Ting 0.6.1: вікно доступності', paragraphs: ['Якщо мікрозастосунку потрібна доступність (виділений текст, переднє вікно, keys, paste або output to: [app]), а в Ting її немає, Ting відкриває вікно з кроками замість панелі з помилкою чи системного запиту macOS. Кнопка Open Accessibility Settings відкриває розділ доступності в налаштуваннях приватності й безпеки; перетягніть іконку Ting із вікна в список застосунків або натисніть + і виберіть Ting, потім увімкніть перемикач. Вікно лишається поверх системних налаштувань і закривається саме, коли доступ увімкнено; після цього запустіть мікрозастосунок знову. Результат, який не вдалося вставити, лишається в буфері обміну.', 'Settings › Advanced показує, чи має Ting доступність; кнопка Allow… відкриває те саме вікно. Помітні кнопки у світлій темі тепер світло-бурштинові, їхній текст легше читати. Щоб установити 0.6.1, виберіть Check for Updates… у Ting. Налаштування, прив’язки, мікрозастосунки та дозволи збережуться.'] },
      { title: 'Ting 0.6.0: контекст і введення', paragraphs: ['Мікрозастосунок перелічує в context: те, що Ting читає під час запуску, і Ting читає лише це: app (назва, bundle id, шлях), finder (виділені файли й папка переднього вікна Finder, навіть якщо Finder у фоні), browser (URL і заголовок передньої вкладки в Safari, Chrome, Arc, Brave, Edge, Vivaldi або Chromium), selection (виділений текст) і window (заголовок і документ переднього вікна). Кроки читають їх як ${context.finder.selection}, код — як $TING_CONTEXT_FINDER_SELECTION. Нові приклади: About the active app, Checksum of Finder files, Copy page link, Sort selected lines і Search in a new tab.', 'Крок keys натискає клавіші в застосунку, який був попереду, наприклад keys: [cmd+a, return]; крок paste вставляє туди текст; output to: [app] вставляє результат. Спершу Ting закриває свою панель, а після вставлення повертає попередній буфер обміну. Якщо той застосунок уже не попереду або клавіатуру тримає поле пароля, Ting нічого не надсилає. ting-micro run приймає значення через --context і ніколи не надсилає клавіші.', 'Ting запитує дозволи, лише коли вони потрібні мікрозастосунку: автоматизацію для Finder або браузера (macOS запитує один раз для кожного застосунку) і доступність для виділеного тексту, вікна, keys, paste та виводу в застосунок. Якщо застосунок не віддає виділений текст через доступність, Ting натискає в ньому Command-C і повертає буфер обміну. Щоб установити 0.6.0, виберіть Check for Updates… у Ting. Налаштування, прив’язки та мікрозастосунки збережуться.'] },
      { title: 'Ting 0.5.1: швидше меню та перемикання', paragraphs: ['Під час завантаження прив’язок, зокрема вкладених груп, Ting заздалегідь завантажує іконки та кешує шляхи застосунків. Уже запущені застосунки активуються напряму, до приховування меню початкової клавіші. Подання меню використовується повторно, а не створюється заново під час кожного відкриття; вікно відповідає розміру меню й використовує системну тінь.', 'Малі клавіші мають однакову мінімальну ширину, з другою літерою розкладки чи без неї. Рядки пробілу та інших клавіш без цієї літери більше не зсуваються вліво. Щоб установити 0.5.1, виберіть Check for Updates… у Ting. Налаштування, прив’язки та мікрозастосунки збережуться.'] },
      { title: 'Ting 0.5.0: кроки та бібліотеки', paragraphs: ['Мікрозастосунок у ~/.config/ting/micro/ тепер може виконувати список кроків замість однієї команди: command (оболонка), python, url (HTTP-запит), ai (OpenAI, Anthropic або будь-який OpenAI-сумісний сервер), text, json, open і notify. Вивід кожного кроку йде на вхід наступному. Кроки читають параметри, вивід попередніх кроків, середовище вашої оболонки входу та записи зв’язки ключів, тож API-ключі не потрапляють у файли. Відповіді ШІ та довгий вивід з’являються в панелі в міру надходження. Старі мікрозастосунки працюють як раніше; якщо у файлі вказано timeout, запуск може тривати до 300 секунд.', 'Кроки, спільні для кількох мікрозастосунків, зберігаються один раз у ~/.config/ting/micro/libs/. Мікрозастосунок запускає бібліотеку через call або успадковує її через inherit і змінює лише частину значень, наприклад один мікрозастосунок перекладу на кожну мову. Після зміни бібліотеки Ting знову просить схвалити кожен мікрозастосунок, який її використовує.', 'Ting.app/Contents/MacOS/ting-micro перевіряє мікрозастосунки (check), запускає їх у терміналі без панелей і буфера обміну (run) та перевіряє config.json (check-config). Новий посібник CONFIGURING.md усередині Ting.app пояснює Claude Code, Codex або pi, як додавати мікрозастосунки, прив’язки клавіш і налаштування; Copy Agent Prompt тепер веде до нього. Просіть звичайними словами, наприклад «Leader t a має перекладати буфер обміну німецькою». Крок notify під час першого сповіщення запитує дозвіл на сповіщення.'] },
      { title: 'Ting 0.4.0: мікрозастосунки', paragraphs: ['Мікрозастосунок — невеликий інструмент, що запускає одну команду оболонки. Кожен — це YAML-файл у ~/.config/ting/micro/ у форматі FORMAT.md. Цей документ лежить усередині Ting.app і містить п’ять робочих прикладів: Format JSON, Change case, Encode / decode, Count words і DNS lookup. Редактора для них у Ting немає, і сам він нічого не встановлює, тож папка спершу порожня. Прив’яжіть клавішу в Settings › Bindings через + › Micro-app або запустіть мікрозастосунок за назвою з launcha.', 'Перед першим запуском і після будь-якої зміни файлу панель схвалення показує назву, файл і повну команду: Command-Return схвалює, Esc відмовляє. Потім панель параметрів запитує значення й запам’ятовує їх, а панель результату показує вивід як markdown, консольний текст із кольорами, простий текст чи код або копіює його. Помилку команди Ting показує завжди. Файл із помилкою не використовується: меню в рядку меню попереджає, Settings › Advanced перелічує помилки, а micro-errors.log поруч із файлом конфігурації зберігає їх.', 'Copy Agent Prompt у меню рядка меню та в Settings › Advanced копіює готовий текст для агента, наприклад Claude Code, Codex або pi; допишіть, що має робити мікрозастосунок, і вставте текст. Агент пише файл і перевіряє його командою Ting --check, яка не відкриває вікон, не читає конфігурацію й нічого не записує, і не змінює config.json: файл ви схвалюєте під час першого запуску, а клавішу призначаєте самі. Виберіть Check for Updates… у Ting, щоб установити оновлення.'] },
      { title: 'Ting 0.3.3', paragraphs: ['Звук «ting» під час відкриття застосунку, посилання чи файлу тепер удвічі тихіший. Його перемикач у Settings → General → System тепер називається Play a “ting” when opening an app, link or file; вимкніть його, щоб усе відкривалося без звуку. Ключ у конфігурації, як і раніше, playSound. Виберіть Check for Updates… у Ting, щоб установити оновлення.'] },
      { title: 'Ting 0.3.2', paragraphs: ['launcha індексує всі застосунки у своїх папках. Індекс більше не зупиняється через ліміт часу, кількості записів чи глибини папок, підписи про ліміти прибрано. Запити доступу до папок і справжні помилки доступу і далі показуються. Виберіть Check for Updates… у Ting, щоб установити оновлення.'] },
      { title: 'Ting 0.3.1', paragraphs: ['У цьому оновленні зменшено відступ між бурштиновою смугою та рядком початкової клавіші в selecta без заголовка. Тепер він такий самий, як у launcha. Виберіть Check for Updates… у Ting, щоб установити оновлення.'] },
      { title: 'launcha — Ting 0.3.0', paragraphs: ['Ting 0.3.0 додає launcha поруч із меню сталих послідовностей selecta. Двічі натисніть початкову клавішу для пошуку застосунків або призначте окрему гарячу клавішу в Settings; типово її не призначено. Застосунки беруться з /Applications, /System/Applications (зокрема Utilities), ~/Applications і, після згоди, ~/Desktop. Збіги сортуються за кількістю успішних запусків і активацій через Ting за останні сім днів, потім за датою останньої дії. Запуски поза Ting не враховуються. Індекс застосунків оновлюється під час запуску Ting і відкриття launcha. Поки панель відкрита, фонове сканування виконується не частіше разу на хвилину.', 'Якщо за непорожнім запитом немає застосунків, Spotlight шукає індексовані файли в домашній папці, крім прихованих шляхів, ~/Library і пакетів застосунків. Desktop, Documents і Downloads пропускаються до вашої явної згоди; потім macOS може запитати доступ до папок. Дозволи на доступність і моніторинг вводу не потрібні. Стрілки вибирають результат, Return відкриває, Command-Return показує у Finder, Escape закриває.', 'Show panel title діє на обидві панелі. Без заголовка launcha починається з компактного поля пошуку з двома камертонами всередині праворуч; результати залишаються списком. Історія та вибір доступу зберігаються локально в ~/Library/Application Support/Ting/launcha-history.json і launcha-consent.json, окремо від конфігурації. Щоб стерти ці нові дані під час видалення застосунку, видаліть також ~/Library/Application Support/Ting/.'] },
      { title: 'Як безпечно повідомити про проблему', paragraphs: ['Для підтримки використовуйте https://github.com/bobuk-io/ting/issues. Укажіть версії macOS і Ting, кроки відтворення та очікуваний результат. Не публікуйте приватні URL і токени з конфігурації.', 'Про вразливості повідомляйте приватно: https://github.com/bobuk-io/ting/security/advisories/new. Подробиці — у SECURITY.md репозиторію.'] },
      { title: 'Видалення застосунку й даних', paragraphs: [], items: ['Якщо ввімкнено запуск під час входу, спочатку вимкніть його.', 'Закрийте Ting і видаліть /Applications/Ting.app.', 'За бажанням видаліть ~/.config/ting/ для налаштувань, прив’язок, мікрозастосунків і їхнього журналу помилок та ~/Library/Application Support/Ting/ для історії, вибору доступу до папок, схвалень мікрозастосунків і запам’ятованих значень.'] },
    ],
    privacyTitle: 'Ваші сполучення. На вашому Mac.', privacyIntro: 'Як версія Ting із GitHub обробляє налаштування, посилання, мікрозастосунки й оновлення.',
    privacy: [
      { title: 'Локальні налаштування', paragraphs: ['Без облікових записів, аналітики й серверів проєкту. Налаштування та прив’язки залишаються в локальному JSON-файлі ~/.config/ting/config.json. Запуск під час входу використовує системну службу елементів входу macOS. launcha зберігає час успішних запусків через Ting і вибір доступу окремо в ~/Library/Application Support/Ting/launcha-history.json і launcha-consent.json. Запуски поза Ting не відстежуються.', 'Мікрозастосунки — це ваші файли в ~/.config/ting/micro/; micro-errors.log поруч із файлом конфігурації перелічує їхні помилки. Ting зберігає SHA-256 кожного схваленого файлу в ~/Library/Application Support/Ting/micro-approvals.json, а останні значення параметрів кожного мікрозастосунку — звичайним текстом у micro-values.json там само, якщо у файлі не вказано remember: false. Не вводьте секрети в мікрозастосунок, який запам’ятовує значення.'] },
      { title: 'Команди мікрозастосунків', paragraphs: ['Ting запускає команди оболонки лише з файлів мікрозастосунків, які ви схвалили в панелі схвалення, і запитує знову після будь-якої зміни файлу. Команда виконується через /bin/sh -c від вашого імені, з усіма вашими правами та з PATH вашої оболонки входу. Ting ніяк не обмежує її дії: пісочниці немає, команда може читати й змінювати ваші файли, працювати з мережею й запускати інші програми; обмежено лише час роботи: типово 60 секунд, щонайбільше 300. Параметри потрапляють у неї лише як змінні середовища TING_*, а буфер обміну — лише через stdin. Контекст, перелічений у файлі (активний застосунок, виділення у Finder, вкладка браузера, виділений текст, переднє вікно), потрапляє в код як змінні TING_CONTEXT_*; того, чого немає у файлі, Ting не читає. Кроки keys і paste та вивід у застосунок надсилають натискання клавіш і текст у застосунок, який був попереду. Те саме стосується кроків python; кроки url і ai надсилають те, що вказано у файлі, на вказаний там сервер, із ключами з вашого середовища або зв’язки ключів. Мікрозастосунок схвалюється разом із бібліотеками, які він використовує. Схвалюйте лише зрозумілі вам команди.', 'Хто може писати в папку мікрозастосунків, той може запропонувати команду; між таким файлом і запуском стоїть ваше схвалення. Папка мікрозастосунків, config.json і ~/Library/Application Support/Ting/ мають бути доступні на запис лише вашому обліковому запису. Прив’язки до застосунків і URL команд не запускають і аргументів застосункам не передають.'] },
      { title: 'Дозволи', paragraphs: ['Для початкової клавіші Ting використовує стандартний API гарячих клавіш macOS і ніколи не запитує моніторинг вводу. Доступність він запитує, лише коли мікрозастосунок читає виділений текст або переднє вікно, натискає клавіші чи вставляє текст у застосунок, а автоматизацію Finder або браузера — лише коли мікрозастосунок читає виділення у Finder або вкладку браузера. Щоб прочитати виділений текст, який застосунок не віддає через доступність, Ting натискає в ньому Command-C і повертає буфер обміну. launcha сканує папки застосунків під час запуску й відкриття панелі; фонове сканування відкритої панелі — не частіше разу на хвилину. Spotlight шукає індексовані файли вдома лише за непорожнім запитом без збігів застосунків. Приховані шляхи, ~/Library і пакети застосунків виключені. Для Desktop, Documents і Downloads потрібна ваша явна згода; потім macOS може запитати доступ до папок.'] },
      { title: 'Коли використовується мережа', paragraphs: ['Крім того, що роблять схвалені вами мікрозастосунки (їхні команди та кроки url і ai), Ting звертається до мережі лише через Sparkle: він перевіряє стрічку оновлень https://bobuk.io/apps/ting/appcast.xml (Ting 0.6.1 і старші — публічну стрічку релізів GitHub) і завантажує оновлення з GitHub. Сервер bobuk.io бачить звичайні дані кожної перевірки, зокрема IP-адресу; GitHub може обробляти такі самі дані під час завантаження за своєю політикою конфіденційності. Щоб перевіряти оновлення лише тоді, коли хочете, вимкніть автоматичну перевірку в Settings › General.', 'Ting відкриває вказані вами URL типовим застосунком системи. Діє політика відповідного сервісу. Copy Agent Prompt, Ting --check і ting-micro check нічого не надсилають. Завантаження й підтримка розміщені на GitHub, цей сайт — на bobuk.io, його копія — на GitHub Pages.'] },
      { title: 'Як видалити дані', paragraphs: ['Вимкніть запуск під час входу, закрийте Ting і видаліть /Applications/Ting.app. Щоб стерти налаштування, прив’язки та мікрозастосунки, видаліть також ~/.config/ting/. Для історії launcha, вибору доступу до папок, схвалень мікрозастосунків і запам’ятованих значень видаліть ~/Library/Application Support/Ting/.'] },
      { title: 'Питання про дані та безпеку', paragraphs: ['Із запитаннями звертайтеся до підтримки. Не додавайте приватні URL і токени до публічних issue. Для чутливих повідомлень про вразливості використовуйте https://github.com/bobuk-io/ting/security/advisories/new за інструкцією SECURITY.md.'] },
    ],
  },
};
export default copy;
